const setCampaignStatus = `-- name: SetCampaignStatus :one
UPDATE campaigns
SET status             = $1::varchar,
    approver_org_id    = $2::bigint,
    scheduled_at       = $3::timestamptz,
    started_at         = CASE WHEN $1::varchar = 'sending' THEN COALESCE(started_at, NOW())
                              ELSE started_at END,
    finished_at        = CASE WHEN $1::varchar IN ('sent', 'partially_failed', 'cancelled')
                              THEN NOW() ELSE NULL END,
    updated_by_user_id = $4::bigint
WHERE id = $5 AND status = $6::varchar
RETURNING id, uuid, organization_id, brand_id, name, channels, audience_filter, status, scheduled_at, approver_org_id, started_at, finished_at, recipients_total, recipients_sent, recipients_failed, recipients_skipped, created_by_user_id, updated_by_user_id, created_at, updated_at
`

type SetCampaignStatusParams struct {
	Status        string             `json:"status"`
	ApproverOrgID pgtype.Int8        `json:"approver_org_id"`
	ScheduledAt   pgtype.Timestamptz `json:"scheduled_at"`
	ActorUserID   pgtype.Int8        `json:"actor_user_id"`
	ID            int64              `json:"id"`
	FromStatus    string             `json:"from_status"`
}

// Moves the campaign from from_status to status (no row when it moved
// meanwhile). approver_org_id and scheduled_at are replaced by the given
// values; sending stamps started_at, the end states stamp finished_at.
func (q *Queries) SetCampaignStatus(ctx context.Context, arg SetCampaignStatusParams) (Campaign, error) {
	row := q.db.QueryRow(ctx, setCampaignStatus,
		arg.Status,
		arg.ApproverOrgID,
		arg.ScheduledAt,
		arg.ActorUserID,
		arg.ID,
		arg.FromStatus,
	)
	var i Campaign
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.OrganizationID,
		&i.BrandID,
		&i.Name,
		&i.Channels,
		&i.AudienceFilter,
		&i.Status,
		&i.ScheduledAt,
		&i.ApproverOrgID,
		&i.StartedAt,
		&i.FinishedAt,
		&i.RecipientsTotal,
		&i.RecipientsSent,
		&i.RecipientsFailed,
		&i.RecipientsSkipped,
		&i.CreatedByUserID,
		&i.UpdatedByUserID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const skipPendingCampaignRecipients = `-- name: SkipPendingCampaignRecipients :execrows
UPDATE campaign_recipients
SET status = 'skipped',
    reason = $1::text
WHERE campaign_id = $2 AND status = 'pending'
`

type SkipPendingCampaignRecipientsParams struct {
	Reason     string `json:"reason"`
	CampaignID int64  `json:"campaign_id"`
}

// Cancellation while sending: the remaining pending recipients are skipped.
func (q *Queries) SkipPendingCampaignRecipients(ctx context.Context, arg SkipPendingCampaignRecipientsParams) (int64, error) {
	result, err := q.db.Exec(ctx, skipPendingCampaignRecipients, arg.Reason, arg.CampaignID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

